    var ck='ysok_'+md5,cached='';
    try{cached=String(source.get(ck)||'')}catch(e){}
    if(cached&&cached.indexOf('file://')>=0)return cached;
    var dir=url.substring(0,url.lastIndexOf('/')+1);
    var origin=url.substring(0,url.indexOf('/',url.indexOf('//')+2));
    var lines=m3.split(YS_NL),segs=[];
    for(var i=0;i<lines.length;i++){var L=String(lines[i]).trim();if(L&&L.charAt(0)!=='#')segs.push(L.indexOf('http')===0?L:dir+L);}
    if(!segs.length)return url;
