    var C=Packages.javax.crypto.Cipher,K=Packages.javax.crypto.spec.SecretKeySpec,V=Packages.javax.crypto.spec.IvParameterSpec;
    var BAOS=Packages.java.io.ByteArrayOutputStream,bos=new BAOS(),ok=0;
