  var hosts=YS_get('ys_hosts','').split(',');if(!hosts.length||!hosts[0])hosts=YS_DOMAINS.slice(0);
  var i=Number(n)-1;if(i<0||i>=hosts.length){YS_T('❌ 无效编号');return '';}
  var cur='https://'+hosts[i]+':'+YS_PORTS[0];YS_save(cur);YS_T('✅ 已切到'+(i+1)+'号 '+hosts[i]);YS_refreshExplore();return cur;
}
function YS_setPub(){var v=String(result&&result.get?result.get('发布页'):'').trim();if(!v){YS_T('❌ 请填发布页');return '';}if(v.indexOf('http')!==0)v='https://'+v;try{source.put('ys_pub',v)}catch(e){}YS_T('✅ 发布页已设为 '+v);return v;}
function YS_reset(){YS_save(YS_DEF);YS_T('↩️ 已恢复默认线路');YS_refreshExplore();return YS_DEF;}
function YS_status(){
  var ts=YS_get('ys_line_ts','0'),when='从未';if(ts&&ts!='0'){try{when=new Date(Number(ts)).toLocaleString()}catch(e){}}
  YS_T('ℹ 频道: '+YS_curMode()+YS_NL+'线路: '+YS_cur()+YS_NL+'切换: '+when);return YS_cur();
}
